// Conan::ImportStart
#pragma once
#include <infinfer/kernel/kernel.h>
// Conan::ImportEnd

/*
 * k1_mlp3: the PLAN's first model-level KAT -- MLP 16 -> 32 (relu) -> 4, built
 * from the kernels the tree actually ships (fc + relu), no graph interpreter
 * needed. It is the model-level counterpart of k0: k0 proves the pipeline, k1
 * proves that a *chain* of numeric kernels lands on the same bytes everywhere.
 *
 * Weights and the input are generated by an integer LCG compiled into every
 * target, not parsed from a blob: identical integer arithmetic first, then one
 * exact int->float conversion per value, so no libc float parser can differ.
 *
 * k1_mlp3：PLAN 的第一个模型级 KAT —— MLP 16→32（relu）→4，只用本树已有的
 * 算子（fc + relu）搭出，不需要图解释器。它是 k0 的模型级对应物：k0 证明管线，
 * k1 证明"一串数值算子也在所有目标上落到同一份字节"。
 *
 * 权重与输入由编译进每个目标的整数 LCG 生成，而不是解析 blob：先保证整数算术
 * 完全一致，每个值只做一次精确的 int→float 转换，任何 libc 的浮点解析器都无从
 * 产生差异。
 */

#define KAT_K1_IN 16u
#define KAT_K1_HIDDEN 32u
#define KAT_K1_OUT 4u

typedef struct kat_k1_result {
    float x[KAT_K1_IN];      /* Fixed input. 固定输入。 */
    float y1[KAT_K1_HIDDEN]; /* After fc1 + relu. fc1+relu 之后。 */
    float y2[KAT_K1_OUT];    /* After fc2: the checked tensor. fc2 之后（被校验）。 */
} kat_k1_result;

infr_status kat_k1_run(kat_k1_result *out);

/** Checked bytes of the chain's final tensor. 被校验的最终张量字节。 */
unsigned kat_k1_expect_len(void);
void kat_k1_expect(const kat_k1_result *result, unsigned char *dst);
